using System;
using System.Drawing;
using System.IO;
using System.Windows.Forms;
using MyDay.Windows.Core;
using MyDay.Windows.UI;
namespace MyDay.Windows
{
    internal static partial class Tests
    {
        private static void BakeTime(CookingGame game,double seconds){for(int i=0;i<(int)Math.Round(seconds*120);i++)game.Step(1.0/120);}
        private static void BakeTo(CookingGame game,double heat){while(game.Breathing&&game.Heat<heat)game.Step(1.0/120);}
        private static void RunCookingTests(string directory)
        {
            var game=new CookingGame();Check(!game.BeginHeat()&&!game.ReleaseHeat()&&game.State==SnackRoundState.Ready,"Cooking waits for an explicit start and hold");game.Start();Check(game.BeginHeat()&&!game.BeginHeat(),"Cooking starts one flame per fresh hold");BakeTo(game,20);Check(game.Heat>19&&game.Breathing,"Holding gradually heats the snack");game.ReleaseHeat();Check(game.Outcome==BakeOutcome.Under&&game.Score==0&&game.Completed==1&&!game.Breathing,"An early release gives undercooked feedback without points");Check(!game.ReleaseHeat()&&game.Completed==1,"Repeated releases cannot consume another order");BakeTime(game,1);Check(game.OrderIndex==1&&game.Recipe=="식빵"&&game.Phase==CookingPhase.ReadyItem,"Feedback advances to the next recipe without automatic heating");
            game.BeginHeat();BakeTo(game,game.Target-6);game.ReleaseHeat();Check(game.Outcome==BakeOutcome.Good&&game.Score==30&&game.Cooked==1,"The golden zone gives thirty points");int order=game.OrderIndex;BakeTime(game,.4);Check(game.OrderIndex==order,"Feedback preserves the served recipe and target");BakeTime(game,.6);game.BeginHeat();BakeTo(game,game.Target);game.ReleaseHeat();Check(game.Outcome==BakeOutcome.Perfect&&game.Score==80&&game.Perfects==1,"The center zone gives fifty points and a perfect count");
            BakeTime(game,1);game.BeginHeat();BakeTo(game,95);game.ReleaseHeat();Check(game.Outcome==BakeOutcome.Burnt&&game.Score==80,"Late release burns the snack without removing earned points");BakeTime(game,1);game.BeginHeat();BakeTime(game,5);Check(game.Completed==5&&game.Phase==CookingPhase.ReadyItem&&!game.Breathing,"Overheating serves one burnt order and never starts the next one automatically");
            game.BeginHeat();BakeTo(game,30);int before=game.Completed;double time=game.Elapsed;game.Pause();BakeTime(game,1);Check(!game.Breathing&&game.Heat==0&&game.Elapsed==time&&game.Completed==before,"Pause extinguishes unfinished cooking without spending an order or active time");game.Resume();Check(game.BeginHeat(),"Resuming requires and accepts a fresh hold");game.CancelHeat();Check(game.Completed==before&&game.Phase==CookingPhase.ReadyItem&&!game.Breathing,"Lost capture cancels a hold without a phantom serve");
            var a=new CookingGame();var b=new CookingGame();a.Start();b.Start();a.BeginHeat();b.BeginHeat();for(int i=0;i<60;i++)a.Step(1.0/30);for(int i=0;i<240;i++)b.Step(1.0/120);Check(Math.Abs(a.Heat-b.Heat)<.001&&Math.Abs(a.Elapsed-b.Elapsed)<.001,"Cooking heat agrees at thirty and one hundred twenty FPS");a.Step(double.NaN);a.Step(double.PositiveInfinity);a.Step(-1);Check(!double.IsNaN(a.Heat)&&Math.Abs(a.Elapsed-2)<.001,"Invalid cooking frame times are ignored");
            game.Start();BakeTime(game,59);game.BeginHeat();BakeTime(game,1);Check(game.State==SnackRoundState.Finished&&game.Completed==0&&game.Score==0&&!game.Breathing,"Time expiry extinguishes an unfinished order without awarding it");game.Start();for(int i=0;i<MiniGameRules.BakeOrders;i++){game.BeginHeat();BakeTo(game,game.Target);game.ReleaseHeat();BakeTime(game,1);}Check(game.State==SnackRoundState.Finished&&game.Completed==8&&game.Score==400&&game.Perfects==8&&!game.BeginHeat(),"Eight perfect orders finish the round with a bounded score");game.Start();Check(game.Score==0&&game.Completed==0&&game.Heat==0&&game.OrderIndex==0,"Restart clears the previous cooking round");
            string path=Path.Combine(directory,"cooking-best","scores.json");var records=new GameRecords(path);records.Record("snack",10);records.Record("jump",20);records.Record("bake",100);records.Record("bake",30);var reload=new GameRecords(path);Check(reload.Best("bake")==100&&reload.Plays("bake")==2&&reload.Best("snack")==10&&reload.Best("jump")==20,"Cooking scores persist separately alongside previous games");
        }
        private static void CookingFrame(CookingGameWindow w,double seconds){for(int i=0;i<(int)Math.Round(seconds*120);i++)w.Advance(1.0/120);}
        private static void CookingHeat(CookingGameWindow w,double heat){while(w.Game.Breathing&&w.Game.Heat<heat)w.Advance(1.0/120);}
        public static void CookingPreview(string directory)
        {
            Directory.CreateDirectory(directory);var records=new GameRecords();
            using(var hub=new GameHubWindow(records)){hub.Show();Application.DoEvents();hub.VerifyCardsForTest();using(var image=new Bitmap(hub.Width,hub.Height)){hub.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(directory,"windows-cooking-hub.png"));}hub.ClientSize=Design.Size(740,600);Application.DoEvents();hub.VerifyCardsForTest();using(var image=new Bitmap(hub.Width,hub.Height)){hub.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(directory,"windows-cooking-hub-compact.png"));}hub.Close();}
            using(var w=new CookingGameWindow(records)){
                w.Show();Application.DoEvents();w.VerifyFooterForTest();w.StartRound();using(var frame=new Bitmap(w.Width,w.Height)){w.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));frame.Save(Path.Combine(directory,"windows-cooking-window.png"));}w.ClientSize=Design.Size(680,570);Application.DoEvents();w.VerifyFooterForTest();using(var frame=new Bitmap(w.Width,w.Height)){w.DrawToBitmap(frame,new Rectangle(Point.Empty,frame.Size));frame.Save(Path.Combine(directory,"windows-cooking-window-compact.png"));}w.ClientSize=Design.Size(960,740);Application.DoEvents();w.StartRound();var e=w.NativeKeyDownForTest(Keys.Space);if(!e.Handled||e.SuppressKeyPress||!w.Game.Breathing)throw new Exception("Cooking keyboard input suppressed release or did not start fire");CookingHeat(w,w.Game.Target);w.SavePreview(Path.Combine(directory,"windows-cooking.png"));w.NativeKeyDownForTest(Keys.Space);w.EndPointer();w.ButtonCaptureLossForTest();if(!w.Game.Breathing)throw new Exception("Mixed pointer release stole the keyboard hold");w.NativeKeyUpForTest(Keys.Space);if(w.Game.Score!=50||w.Game.Completed!=1)throw new Exception("Cooking key release did not serve one perfect snack");w.SavePreview(Path.Combine(directory,"windows-cooking-perfect.png"));
                CookingFrame(w,1);w.BeginPointer();CookingFrame(w,.3);w.NativeKeyUpForTest(Keys.Space);if(!w.Game.Breathing)throw new Exception("Mixed keyboard release stole a pointer hold");w.CaptureLossForTest();if(w.Game.Breathing||w.Game.Completed!=1)throw new Exception("Cooking lost capture did not cancel safely");w.BeginPointer();CookingFrame(w,.2);w.LoseFocusForTest();double time=w.Game.Elapsed;CookingFrame(w,1);if(w.Game.Breathing||w.Game.Completed!=1||w.Game.Elapsed!=time)throw new Exception("Cooking native pause failed");w.TogglePause();w.EndPointer();if(w.Game.Completed!=1)throw new Exception("A stale release after resume served a snack");
                w.NativeKeyDownForTest(Keys.Space);CookingFrame(w,3.2);if(w.Game.Breathing||w.Game.Completed!=2)throw new Exception("Cooking auto-burn did not end held fire");w.SavePreview(Path.Combine(directory,"windows-cooking-burnt.png"));CookingFrame(w,1);w.NativeKeyDownForTest(Keys.Space);if(w.Game.Breathing)throw new Exception("Cooking key repeat heated the next order");w.NativeKeyUpForTest(Keys.Space);
                while(w.Game.State==SnackRoundState.Playing){if(w.Game.Phase==CookingPhase.ReadyItem){w.BeginPointer();CookingHeat(w,w.Game.Target);w.EndPointer();}CookingFrame(w,1);}w.Advance(.1);if(records.Plays("bake")!=1||records.Best("bake")!=350)throw new Exception("Cooking round did not save its score exactly once");w.SavePreview(Path.Combine(directory,"windows-cooking-result.png"));MiniGameArt.WriteResult(Path.Combine(directory,"windows-cooking-card.png"),new MiniGameResult{Name="상몬 불꽃 요리",Day=DateTime.Today,Score=w.Game.Score,Details="완성 "+w.Game.Cooked+"개 · 완벽 "+w.Game.Perfects+"개"});w.Close();
            }
            Console.WriteLine("Native cooking: five-game hub at full/compact size, keyboard release, mixed input, capture cancellation, pause, held-key overheat, single score save and PNG export passed.");
        }
    }
}
